using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.DTOs;
using EmployeeMonitoringAPI.Interfaces;
using EmployeeMonitoringAPI.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
namespace EmployeeMonitoringAPI.Controllers;
[Route("api/[controller]")][ApiController][Authorize]
public sealed class ProfileController:ControllerBase
{
 private readonly ApplicationDbContext _db;private readonly IWebHostEnvironment _environment;private readonly IAuditService _audit;public ProfileController(ApplicationDbContext db,IWebHostEnvironment environment,IAuditService audit){_db=db;_environment=environment;_audit=audit;}
 [HttpGet]public async Task<IActionResult> Get(){var id=CurrentUserId();var user=await _db.Users.AsNoTracking().Include(x=>x.Department).Include(x=>x.Manager).FirstOrDefaultAsync(x=>x.UserId==id);if(user is null)return NotFound();var pref=await _db.EmployeePreferences.AsNoTracking().FirstOrDefaultAsync(x=>x.UserId==id);return Ok(new{user.UserId,user.FullName,user.Email,user.Username,user.Role,user.IsActive,user.ProfileImage,adminCode=user.EmployeeCode,user.EmployeeCode,user.PhoneNumber,user.Designation,user.DateOfJoining,user.Address,user.MfaEnabled,user.LastPasswordChangedAt,themePreference=pref?.Theme,notificationPreference=pref?.EmailNotifications==true?"All":"None",Department=user.Department?.Name,Manager=user.Manager?.FullName});}
 [HttpGet("mfa-status")]public async Task<IActionResult> MfaStatus(){var id=CurrentUserId();var user=await _db.Users.AsNoTracking().FirstOrDefaultAsync(x=>x.UserId==id);if(user is null)return NotFound();var key=$"MfaRequiredFor{user.Role}";var configured=await _db.SystemSettings.Where(x=>x.SettingKey==key).Select(x=>x.SettingValue).FirstOrDefaultAsync();var required=user.Role=="Admin"||bool.TryParse(configured,out var value)&&value;var phone=user.PhoneNumber;var masked=string.IsNullOrWhiteSpace(phone)?null:phone.Length<=4?"****":new string('*',phone.Length-4)+phone[^4..];return Ok(new{status=required?"Required by Company":user.MfaEnabled?"Enabled":"Disabled",requiredByCompany=required,user.MfaEnabled,maskedPhone=masked,policy=required?"Multi-factor authentication is required by company policy and cannot be disabled.":"Multi-factor authentication is configurable for this role."});}
 [HttpPut]public async Task<IActionResult> Update(LimitedProfileDto dto){var id=CurrentUserId();var user=await _db.Users.FindAsync(id);if(user is null)return NotFound();user.PhoneNumber=dto.PhoneNumber?.Trim();user.Address=dto.Address?.Trim();var pref=await _db.EmployeePreferences.FirstOrDefaultAsync(x=>x.UserId==id);if(pref is null){pref=new EmployeePreference{UserId=id};_db.EmployeePreferences.Add(pref);}if(!string.IsNullOrWhiteSpace(dto.ThemePreference))pref.Theme=dto.ThemePreference;if(!string.IsNullOrWhiteSpace(dto.NotificationPreference))pref.EmailNotifications=!dto.NotificationPreference.Equals("None",StringComparison.OrdinalIgnoreCase);pref.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await _audit.RecordAsync("ProfileUpdated","User",id.ToString(),actorUserId:id);return Ok(new{message="Profile updated"});}
 [HttpPost("upload-image")][RequestSizeLimit(5_000_000)]public async Task<IActionResult> Upload(IFormFile file){var id=CurrentUserId();var user=await _db.Users.FindAsync(id);if(user is null)return NotFound();if(file is null||file.Length==0||file.Length>5_000_000)return BadRequest(new{message="A profile image up to 5 MB is required"});var allowed=new[]{".jpg",".jpeg",".png",".webp"};var extension=Path.GetExtension(file.FileName).ToLowerInvariant();if(!allowed.Contains(extension))return BadRequest(new{message="Only JPG, PNG and WEBP images are supported"});var root=_environment.WebRootPath??Path.Combine(Directory.GetCurrentDirectory(),"wwwroot");var folder=Path.Combine(root,"uploads");Directory.CreateDirectory(folder);var name=Guid.NewGuid().ToString("N")+extension;await using(var stream=System.IO.File.Create(Path.Combine(folder,name)))await file.CopyToAsync(stream);user.ProfileImage="/uploads/"+name;await _db.SaveChangesAsync();await _audit.RecordAsync("ProfileImageUpdated","User",id.ToString(),actorUserId:id);return Ok(new{imageUrl=user.ProfileImage});}
 private int CurrentUserId()=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
}
